#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gemver.h"

/* Include the Exo-generated kernel header. */
#include "generated/gemver/gemver.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE *alpha,
		 DATA_TYPE *beta,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_1D(u1,N,n),
		 DATA_TYPE POLYBENCH_1D(v1,N,n),
		 DATA_TYPE POLYBENCH_1D(u2,N,n),
		 DATA_TYPE POLYBENCH_1D(v2,N,n),
		 DATA_TYPE POLYBENCH_1D(w,N,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;

  DATA_TYPE fn = (DATA_TYPE)n;

  for (i = 0; i < n; i++)
    {
      u1[i] = i;
      u2[i] = ((i+1)/fn)/2.0;
      v1[i] = ((i+1)/fn)/4.0;
      v2[i] = ((i+1)/fn)/6.0;
      y[i] = ((i+1)/fn)/8.0;
      z[i] = ((i+1)/fn)/9.0;
      x[i] = 0.0;
      w[i] = 0.0;
      for (j = 0; j < n; j++)
        A[i][j] = (DATA_TYPE) (i*j % n) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(w,N,n))
{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("w");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, w[i]);
  }
  POLYBENCH_DUMP_END("w");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo (optimized with scheduling):
EXO START
from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *


# Baseline algorithm, already structured for good locality:
#  - First loop nest fuses the A update and the x update.
#    We traverse A row-major (j = row, i = column) and keep
#    row-wise scalars (u1[j], u2[j], y[j]) in registers.
#  - Second loop adds z into x.
#  - Third loop computes w = w + alpha * A * x, accumulating
#    each w[i] in a scalar before writing it back.
@proc
def kernel_gemver_base(
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    A: DATA_TYPE[n, n] @ DRAM,
    u1: DATA_TYPE[n] @ DRAM,
    v1: DATA_TYPE[n] @ DRAM,
    u2: DATA_TYPE[n] @ DRAM,
    v2: DATA_TYPE[n] @ DRAM,
    w: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    z: DATA_TYPE[n] @ DRAM,
):

    # Fused version of:
    #   A[i,j] += u1[i]*v1[j] + u2[i]*v2[j]
    #   x[i]   += beta * A[j,i] * y[j]
    # We iterate row-major over A[j,i] so that:
    #   - A[j, i], v1[i], v2[i], x[i] are all accessed with
    #     contiguous i in the innermost loop.
    for j in seq(0, n):
        u1j: DATA_TYPE
        u2j: DATA_TYPE
        yj: DATA_TYPE
        beta_yj: DATA_TYPE

        u1j = u1[j]
        u2j = u2[j]
        yj = y[j]
        beta_yj = beta * yj

        for i in seq(0, n):
            a_ji: DATA_TYPE

            # Update A[j, i] with the two rank-1 outer products.
            a_ji = A[j, i] + u1j * v1[i] + u2j * v2[i]
            A[j, i] = a_ji

            # x[i] accumulates beta * A[j, i] * y[j] over all j.
            x[i] += beta_yj * a_ji

    # x[i] += z[i]
    for i in seq(0, n):
        x[i] += z[i]

    # w[i] += alpha * sum_j A[i, j] * x[j]
    # Accumulate in a register wi for better performance.
    for i in seq(0, n):
        wi: DATA_TYPE
        wi = w[i]
        for j in seq(0, n):
            wi = wi + alpha * A[i, j] * x[j]
        w[i] = wi


# =====================
# Scheduling / tuning
# =====================
p = kernel_gemver_base

# Parallelize the outer loop of the final GEMV-like phase
#   for i in seq(0, n): ...
# which is the 3rd loop whose iterator is named "i".
p = parallelize_loop(p, "i #2")

# Tile the inner j-loop of the w update to improve cache usage
# and enable better vectorization. The tile size can be tuned.
tile_size = 32
p = divide_loop(p, "j #1", tile_size, ["jo", "ji"], tail="guard")

# (Optional) run simplification to clean up the resulting IR.
p = simplify(p)

# Expose the optimized kernel under the externally visible name.
kernel_gemver = rename(p, "kernel_gemver")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(u1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(u2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(w,  DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x,  DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y,  DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(z,  DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(u1),
	      POLYBENCH_ARRAY(v1),
	      POLYBENCH_ARRAY(u2),
	      POLYBENCH_ARRAY(v2),
	      POLYBENCH_ARRAY(w),
	      POLYBENCH_ARRAY(x),
	      POLYBENCH_ARRAY(y),
	      POLYBENCH_ARRAY(z));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten PolyBench views to raw pointers. */
  kernel_gemver(/*ctxt=*/NULL, n,
                (DATA_TYPE*)&alpha,
                (DATA_TYPE*)&beta,
                (DATA_TYPE*)POLYBENCH_ARRAY(A),
                (DATA_TYPE*)POLYBENCH_ARRAY(u1),
                (DATA_TYPE*)POLYBENCH_ARRAY(v1),
                (DATA_TYPE*)POLYBENCH_ARRAY(u2),
                (DATA_TYPE*)POLYBENCH_ARRAY(v2),
                (DATA_TYPE*)POLYBENCH_ARRAY(w),
                (DATA_TYPE*)POLYBENCH_ARRAY(x),
                (DATA_TYPE*)POLYBENCH_ARRAY(y),
                (DATA_TYPE*)POLYBENCH_ARRAY(z));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(w)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(u1);
  POLYBENCH_FREE_ARRAY(v1);
  POLYBENCH_FREE_ARRAY(u2);
  POLYBENCH_FREE_ARRAY(v2);
  POLYBENCH_FREE_ARRAY(w);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(z);

  return 0;
}
