def kernel_gemver(
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    A: DATA_TYPE[n, n] @ DRAM,
    u1: DATA_TYPE[n] @ DRAM,
    v1: DATA_TYPE[n] @ DRAM,
    u2: DATA_TYPE[n] @ DRAM,
    v2: DATA_TYPE[n] @ DRAM,
    w: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    z: DATA_TYPE[n] @ DRAM,
):
    # 1) Rank-2 update on A: A += u1 * v1^T + u2 * v2^T
    #    Access pattern is row-major in A (i outer, j inner).
    for i in seq(0, n):
        for j in seq(0, n):
            A[i, j] += u1[i] * v1[j] + u2[i] * v2[j]

    # 2) x += beta * A^T * y
    #    We rewrite the original i-j loop as j-i:
    #      for j: (row of A)
    #        beta_yj = beta * y[j]
    #        for i:
    #          x[i] += A[j, i] * beta_yj
    #    This keeps A accesses row-major (good locality) and
    #    loads y[j] only once per j.
    for j in seq(0, n):
        beta_yj: DATA_TYPE
        beta_yj = beta * y[j]
        for i in seq(0, n):
            x[i] += A[j, i] * beta_yj

    # 3) x += z
    for i in seq(0, n):
        x[i] += z[i]

    # 4) w += alpha * A * x
    #    Accumulate into a scalar wi to avoid repeated loads/stores of w[i]
    #    inside the inner loop.
    for i in seq(0, n):
        wi: DATA_TYPE
        wi = w[i]
        for j in seq(0, n):
            wi += alpha * A[i, j] * x[j]
        w[i] = wi


# =========================
# Scheduling / optimization
# =========================

p = kernel_gemver

# The kernel body consists of four top-level loops in order:
#   0: rank-2 update on A
#   1: x += beta * A^T * y
#   2: x += z
#   3: w += alpha * A * x
body = p.body()

# Parallelize the rank-2 update on A over rows (i loop).
# Each iteration touches a distinct row of A and independent
# entries of u1/u2, so this is safely parallelizable.
p = parallelize_loop(p, body[0])

# Parallelize the final w update over rows (i loop).
# Each iteration updates a distinct w[i] and reads a single row of A,
# so there are no cross-iteration dependencies.
p = parallelize_loop(p, body[3])

# Use the scheduled version as the exported kernel.
kernel_gemver = p
